def p(slug, photos, name, name_ar, scientific, confidence, category, light, watering, care, placement, desc, desc_ar, note=None):
    return dict(slug=slug, photos=photos, name=name, nameAr=name_ar, scientificName=scientific, confidence=confidence,
                category=category, light=light, watering=watering, careLevel=care, placement=placement,
                description=desc, descriptionAr=desc_ar, note=note)


